    float4 color : TEXCOORD8;
    nointerpolation uint  instanceIndex : TEXCOORD4;
    nointerpolation float winding : TEXCOORD5;
    float2 uv1 : TEXCOORD6;
    nointerpolation float3 dielectric : TEXCOORD7;
